def perevod(n):
    if n == 0:
        return '0'
    s = ''
    while n != 0:
        s = str(n % 4) + s
        n //= 4
    return s
def f(n):
    s = perevod(n)
    if n % 2 == 0:
        s = '12' + s + perevod(int(s[-1],4) * 3)
    else:
        s = '13' + s + '21'
    return int(s,4)
mi = float('inf')
for i in range(0,1000):
    if f(i) > 50:
        mi = min(f(i),mi)
print(mi)
